-- Solo para pruebas en una base vacia: replica la tabla users de Laravel (con los campos institucionales).
CREATE TABLE users (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(255) NOT NULL, email varchar(255) NOT NULL UNIQUE, password varchar(255) NOT NULL DEFAULT 'x', cedula varchar(10) UNIQUE, cargo varchar(120), unidad varchar(120), activo boolean NOT NULL DEFAULT true, created_at timestamp, updated_at timestamp);
